async () => {
const res = {};
const radios = [...document.querySelectorAll('input[type=radio]')];
const get = n => radios.filter(r=>r.name===n);
const colorR = radios.filter(r=>['Blue','Black','Olive'].includes(r.value) || /blue|black|olive/i.test(r.value));
const sizeR = radios.filter(r=>/^(XS|S|M|L|XL)$/.test(r.value));
for (const c of colorR) {
  if (c.disabled) { res[c.value] = 'disabled'; continue; }
  c.click(); await new Promise(r=>setTimeout(r,200));
  const m = sizeR.find(s=>s.value==='M');
  res[c.value] = {M_disabled: m.disabled, label: m.closest('label')?.innerText, note: document.body.innerText.match(/Only \d+ left in \w+|Out of stock[^\n]*/g)};
}
return res;
}

